class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = []
        for i in range(n):
            val = nums[i]
            if val > 0:
                # Move val steps to the right
                # Right movement: (i + val) % n
                result.append((i + val) % n)
            elif val < 0:
                # Move abs(val) steps to the left
                # Left movement: (i - abs(val)) % n
                result.append((i - abs(val)) % n)
            else:
                # val == 0
                result.append(val)
        return result
```

