import sys

def solve():
    # Read all input from standard input
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        R = int(next(iterator))
    except StopIteration:
        return

    current_rating = R

    for _ in range(N):
        D = int(next(iterator))
        A = int(next(iterator))

        # Determine if rating update is allowed based on current rating
        # Div. 1: [1600, 2799]
        # Div. 2: [1200, 2399]

        if D == 1:
            if 1600 <= current_rating <= 2799:
                current_rating += A
        elif D == 2:
            if 1200 <= current_rating <= 2399:
                current_rating += A
        # If not subject to rating update, rating does not change.

    print(current_rating)

if __name__ == '__main__':
    solve()
