class Solution:
    def calculateScore(self, s: str) -> int:
        # Map each letter to its mirror in the alphabet
        mirror_map = {chr(i): chr(125 - i) for i in range(26)}

        score = 0
        marked = [False] * len(s)

        for i in range(len(s)):
            if not marked[i]:
                char = s[i]
                mirror_char = mirror_map[char]

                # Find the closest unmarked index j < i with mirror character
                for j in range(i - 1, -1, -1):
                    if not marked[j] and s[j] == mirror_char:
                        score += (i - j)
                        marked[j] = True
                        marked[i] = True
                        break

        return score
```

