class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        def generate_splits(word: str, numFriends: int, splits: list):
            if len(word) == 1:
                splits.append(word)
                return
            for i in range(1, numFriends + 1):
                if i > len(word):
                    continue
                if i > len(word) // (numFriends + 1):
                    continue
                for j in range(i, len(word) + 1):
                    prefix = word[:j]
                    suffix = word[j:]
                    if len(prefix) == 1:
                        splits.append(prefix)
                        splits.append(suffix)
                    else:
                        splits.append(prefix)
                        splits.append(suffix)
            return

        def find_max_split(splits):
            if not splits:
                return ""
            return max(splits)

        def find_best_split(word: str, numFriends: int, current_splits: list):
            if numFriends == 1:
                return word
            if len(word) == 1:
                return word
            best = ""
            for i in range(1, len(word) + 1):
                prefix = word[:i]
                suffix = word[i:]
                if len(prefix) == 1:
                    current_splits.append(prefix)
                    best = max(best, find_best_split(suffix, numFriends - 1, current_splits))
                else:
                    current_splits.append(prefix)
                    best = max(best, find_best_split(suffix, numFriends - 1, current_splits))
            return best

        def dfs(word: str, numFriends: int, current_splits: list):
            if numFriends == 1:
                if current_splits:
                    return current_splits[-1]
                return ""
            if len(word) == 1:
                return word
            max_s = ""
            for i in range(1, len(word) + 1):
                prefix = word[:i]
                suffix = word[i:]
                if len(prefix) == 1:
                    new_splits = current_splits + [prefix]
                    result = dfs(suffix, numFriends - 1, new_splits)
                    if result:
                        max_s = max(max_s, result)
                else:
                    new_splits = current_splits + [prefix]
                    result = dfs(suffix, numFriends - 1, new_splits)
                    if result:
                        max_s = max(max_s, result)
            return max_s

        splits = []
        for i in range(1, numFriends + 1):
            if i > len(word):
                continue
            for j in range(i, len(word) + 1):
                prefix = word[:j]
                suffix = word[j:]
                if len(prefix) == 1:
                    splits.append(prefix)
                    splits.append(suffix)
                else:
                    splits.append(prefix)
                    splits.append(suffix)
        return find_max_split(splits)
