import sys

def solve():
    # Read H, W, D
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    H = int(data[0])
    W = int(data[1])
    D = int(data[2])

    # Read the grid
    grid = []
    idx = 3
    for i in range(H):
        row = data[idx : idx + W]
        grid.append(row)
        idx += W

    # Find all floor cells
    floor_cells = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == '.':
                floor_cells.append((r, c))

    max_humidified = 0

    # Iterate over all pairs of distinct floor cells
    n = len(floor_cells)
    for i in range(n):
        for j in range(i + 1, n):
            u = floor_cells[i]
            v = floor_cells[j]

            # Count humidified cells for this pair
            humidified_count = 0
            for r in range(H):
                for c in range(W):
                    if grid[r][c] == '.':
                        dist_u = abs(r - u[0]) + abs(c - u[1])
                        dist_v = abs(r - v[0]) + abs(c - v[1])

                        if dist_u <= D or dist_v <= D:
                            humidified_count += 1

            if humidified_count > max_humidified:
                max_humidified = humidified_count

    print(max_humidified)

if __name__ == '__main__':
    solve()
